<?php
namespace Tests\Feature;
use App\Models\User;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class StaffPayrollTest extends TestCase {
 use RefreshDatabase;
 protected function beforeRefreshingDatabase():void{if(!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Dedicated test database required.');}
 protected function setUp():void{parent::setUp();\Carbon\Carbon::setTestNow('2026-10-18 08:00:00');}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();parent::tearDown();}
 private function fixture(string $code='A'):array{if(!DB::table('roles')->exists())$this->seed(DatabaseSeeder::class);$sid=DB::table('schools')->insertGetId(['name'=>'Payroll '.$code,'code'=>$code,'status'=>'active','timezone'=>'Asia/Karachi','currency'=>'PKR']);$campus=DB::table('campuses')->insertGetId(['school_id'=>$sid,'name'=>'Main','code'=>'MAIN','status'=>'active']);$owner=User::factory()->create();$omid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$owner->id,'status'=>'active']);DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$omid,'role_id'=>DB::table('roles')->where('name','owner')->value('id')]);$employee=User::factory()->create();$mid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$employee->id,'status'=>'active']);DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$mid,'role_id'=>DB::table('roles')->where('name','teacher')->value('id')]);foreach([$omid,$mid] as $m)DB::table('membership_campuses')->insert(['school_id'=>$sid,'membership_id'=>$m,'campus_id'=>$campus]);$staff=DB::table('staff_profiles')->insertGetId(['school_id'=>$sid,'membership_id'=>$mid,'employee_no'=>'EMP-1','designation'=>'Teacher','hired_on'=>'2026-08-01','status'=>'active']);$employment=DB::table('staff_employments')->insertGetId(['school_id'=>$sid,'staff_profile_id'=>$staff,'campus_id'=>$campus,'starts_on'=>'2026-08-01']);$salary=DB::table('salary_structures')->insertGetId(['school_id'=>$sid,'staff_profile_id'=>$staff,'starts_on'=>'2026-08-01','status'=>'active']);foreach([['Basic','basic','30000'],['Allowance','allowance','3000'],['Fixed deduction','deduction','1000']] as [$name,$kind,$amount])DB::table('salary_structure_items')->insert(['school_id'=>$sid,'salary_structure_id'=>$salary,'name'=>$name,'kind'=>$kind,'amount'=>$amount]);$policy=DB::table('payroll_policies')->insertGetId(['school_id'=>$sid,'campus_id'=>$campus,'starts_on'=>'2026-09-01','version'=>1,'rules'=>json_encode($this->rules()),'created_by'=>$omid]);return compact('sid','campus','owner','omid','employee','mid','staff','employment','salary','policy');}
 private function rules(string $mode='fixed'):array{return ['mode'=>$mode,'weekdays'=>[1,2,3,4,5,6],'deduction_basis'=>'basic','deduct_absence'=>true,'deduct_unpaid_leave'=>true,'late_per_day'=>3];}
 private function login(array $f,bool $employee=false):void{$this->actingAs($f[$employee?'employee':'owner'])->withSession(['school_id'=>$f['sid']]);}
 private function preview(array $f,string $month='2026-09'){return $this->getJson('/app-api/payroll/preview?campus_id='.$f['campus'].'&month='.$month);}
 private function generate(array $f,string $month='2026-09'):int{$p=$this->preview($f,$month)->assertOk()->json();return $this->postJson('/app-api/payroll/generate',['campus_id'=>$f['campus'],'month'=>$month,'source_digest'=>$p['source_digest'],'run_id'=>$p['run_id'],'lock_version'=>$p['lock_version']])->assertOk()->json('id');}
 private function approve(int $run){return $this->postJson('/app-api/payroll/runs/'.$run.'/approve',['lock_version'=>DB::table('payroll_runs')->where('id',$run)->value('lock_version')]);}
 private function item(int $run):int{return (int)DB::table('payroll_items')->where('payroll_run_id',$run)->value('id');}
 private function payData(array $f,int $item,string $amount='10000',string $key='SALARY-PAY-1'):array{return ['campus_id'=>$f['campus'],'staff_profile_id'=>$f['staff'],'amount'=>$amount,'paid_on'=>'2026-10-01','method'=>'cash','bank_account_id'=>null,'reference'=>null,'idempotency_key'=>$key,'allocations'=>[['payroll_item_id'=>$item,'amount'=>$amount]]];}
 private function loan(array $f):int{$id=$this->postJson('/app-api/payroll/advances',['campus_id'=>$f['campus'],'staff_profile_id'=>$f['staff'],'requested_on'=>'2026-08-20','amount'=>'12000','monthly_recovery'=>'5000','reason'=>'Approved personal advance'])->assertOk()->json('id');$this->postJson('/app-api/payroll/advances/'.$id.'/action',['action'=>'approve','lock_version'=>0])->assertOk();$this->postJson('/app-api/payroll/advances/'.$id.'/action',['action'=>'disburse','lock_version'=>1,'paid_on'=>'2026-08-31','method'=>'cash','bank_account_id'=>null,'reference'=>null,'idempotency_key'=>'ADVANCE-'.$id])->assertOk();return $id;}
 public function test_payroll_preview_draft_recalculation_approval_and_snapshots_keep_money_and_history():void{$f=$this->fixture();$this->login($f);$this->preview($f)->assertOk()->assertJsonPath('totals.gross','33000.00')->assertJsonPath('totals.net','32000.00')->assertJsonPath('rows.0.attendance.unmarked',26);$run=$this->generate($f);$item=$this->item($run);$this->assertSame($run,$this->generate($f));$this->assertSame($item,$this->item($run));$this->assertDatabaseCount('salary_payments',0);$this->assertDatabaseCount('advance_recoveries',0);$this->approve($run)->assertOk();$this->approve($run)->assertUnprocessable();DB::table('users')->where('id',$f['employee']->id)->update(['name'=>'Renamed employee']);DB::table('schools')->where('id',$f['sid'])->update(['name'=>'Renamed school']);$slip=$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertOk();$slip->assertJsonPath('item.snapshot.name',$f['employee']->name)->assertJsonPath('item.snapshot.school_name','Payroll A')->assertJsonPath('totals.balance','32000.00');$this->preview($f)->assertUnprocessable();$this->artisan('database:verify')->assertSuccessful();}
 public function test_salary_effective_dates_prorate_and_overlap_or_approved_history_cannot_be_rewritten():void{$f=$this->fixture();$this->login($f);$d=['staff_profile_id'=>$f['staff'],'starts_on'=>'2026-09-16','ends_on'=>null,'replace_previous'=>false,'items'=>[['name'=>'Basic','kind'=>'basic','amount'=>'36000']]];$this->postJson('/app-api/payroll/salaries',$d)->assertUnprocessable();$d['replace_previous']=true;$this->postJson('/app-api/payroll/salaries',$d)->assertOk();$this->preview($f)->assertJsonPath('totals.gross','34500.00')->assertJsonPath('totals.deductions','500.00')->assertJsonPath('totals.net','34000.00');$run=$this->generate($f);$this->approve($run)->assertOk();$d['starts_on']='2026-09-20';$this->postJson('/app-api/payroll/salaries',$d)->assertUnprocessable();}
 public function test_attendance_policy_requires_explicit_marks_and_applies_absence_unpaid_leave_and_late_groups():void{$f=$this->fixture();$this->login($f);DB::table('payroll_policies')->where('id',$f['policy'])->update(['rules'=>json_encode($this->rules('attendance'))]);$this->preview($f)->assertUnprocessable();$paid=DB::table('leave_requests')->insertGetId(['school_id'=>$f['sid'],'staff_profile_id'=>$f['staff'],'starts_on'=>'2026-09-05','ends_on'=>'2026-09-05','leave_type'=>'paid','status'=>'approved','approved_by'=>$f['omid']]);$unpaid=DB::table('leave_requests')->insertGetId(['school_id'=>$f['sid'],'staff_profile_id'=>$f['staff'],'starts_on'=>'2026-09-07','ends_on'=>'2026-09-07','leave_type'=>'unpaid','status'=>'approved','approved_by'=>$f['omid']]);for($day=1;$day<=30;$day++){$date=sprintf('2026-09-%02d',$day);if((int)date('N',strtotime($date))===7)continue;$status=$day===1?'absent':(in_array($day,[2,3,4])?'late':(in_array($day,[5,7])?'leave':'present'));DB::table('staff_attendance_records')->insert(['school_id'=>$f['sid'],'staff_profile_id'=>$f['staff'],'campus_id'=>$f['campus'],'attendance_date'=>$date,'status'=>$status,'recorded_by'=>$f['omid'],'leave_request_id'=>$day===5?$paid:($day===7?$unpaid:null)]);}$this->preview($f)->assertOk()->assertJsonPath('totals.deductions','4000.00')->assertJsonPath('totals.net','29000.00')->assertJsonPath('rows.0.attendance.paid_leave',1)->assertJsonPath('rows.0.attendance.unpaid_leave',1);}
 public function test_stale_preview_and_salary_or_attendance_changes_require_recalculation_before_approval():void{$f=$this->fixture();$this->login($f);$p=$this->preview($f)->assertOk()->json();DB::table('salary_structure_items')->where('salary_structure_id',$f['salary'])->where('kind','allowance')->update(['amount'=>'4000']);$this->postJson('/app-api/payroll/generate',['campus_id'=>$f['campus'],'month'=>'2026-09','source_digest'=>$p['source_digest'],'run_id'=>0,'lock_version'=>0])->assertUnprocessable();$run=$this->generate($f);DB::table('salary_structure_items')->where('salary_structure_id',$f['salary'])->where('kind','allowance')->update(['amount'=>'5000']);$this->approve($run)->assertUnprocessable();$this->generate($f);$this->approve($run)->assertOk();}
 public function test_advance_is_approved_and_disbursed_once_and_recovery_posts_only_on_payroll_approval():void{$f=$this->fixture();$this->login($f);$advance=$this->loan($f);$this->postJson('/app-api/payroll/advances/'.$advance.'/action',['action'=>'disburse','lock_version'=>1,'paid_on'=>'2026-08-31','method'=>'cash','bank_account_id'=>null,'reference'=>null,'idempotency_key'=>'ADVANCE-'.$advance])->assertOk();$this->preview($f)->assertJsonPath('totals.recoveries','5000.00')->assertJsonPath('totals.net','27000.00');$run=$this->generate($f);$this->generate($f);$this->assertDatabaseCount('advance_recoveries',0);$this->approve($run)->assertOk();$this->assertDatabaseCount('advance_recoveries',1);$this->getJson('/app-api/payroll/advances?campus_id='.$f['campus'])->assertJsonPath('rows.0.outstanding','7000.00');$this->postJson('/app-api/payroll/advances/'.$advance.'/action',['action'=>'cancel','lock_version'=>2,'reason'=>'Cannot cancel recovered loan'])->assertUnprocessable();}
 public function test_partial_salary_payments_idempotency_overpayment_and_full_reversal_preserve_receipt():void{$f=$this->fixture();$this->login($f);$run=$this->generate($f);$this->approve($run)->assertOk();$item=$this->item($run);$d=$this->payData($f,$item);$id=$this->postJson('/app-api/payroll/payments',$d)->assertOk()->json('id');$this->postJson('/app-api/payroll/payments',$d)->assertOk()->assertJsonPath('id',$id);$this->assertDatabaseCount('salary_payments',1);$changed=$d;$changed['amount']='1';$changed['allocations'][0]['amount']='1';$this->postJson('/app-api/payroll/payments',$changed)->assertUnprocessable();$this->postJson('/app-api/payroll/payments',$this->payData($f,$item,'23000','SALARY-PAY-OVER'))->assertUnprocessable();$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertJsonPath('totals.paid','10000.00')->assertJsonPath('totals.balance','22000.00');$this->postJson('/app-api/payroll/payments/'.$id.'/reverse',['reason'=>'Correct mistaken payment entry'])->assertOk();$this->postJson('/app-api/payroll/payments/'.$id.'/reverse',['reason'=>'Idempotent reversal review'])->assertOk();$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertJsonPath('totals.paid','0.00')->assertJsonPath('totals.balance','32000.00');$this->getJson('/app-api/payroll/payments/'.$id.'/receipt')->assertOk()->assertJsonPath('payment.amount','10000.00')->assertJsonPath('reversal.reason','Correct mistaken payment entry');}
 public function test_post_approval_adjustments_leave_original_net_immutable_and_cannot_debit_below_payments():void{$f=$this->fixture();$this->login($f);$run=$this->generate($f);$this->approve($run)->assertOk();$item=$this->item($run);$id=$this->postJson('/app-api/payroll/adjustments',['payroll_item_id'=>$item,'kind'=>'credit','amount'=>'500','reason'=>'Approved extra allowance'])->assertOk()->json('id');$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertJsonPath('totals.payable','32000.00');$this->postJson('/app-api/payroll/adjustments/'.$id.'/review',['action'=>'approve','reason'=>'Reviewed allowance correction'])->assertOk();$this->postJson('/app-api/payroll/payments',$this->payData($f,$item,'32500'))->assertOk();$debit=$this->postJson('/app-api/payroll/adjustments',['payroll_item_id'=>$item,'kind'=>'debit','amount'=>'1','reason'=>'Incorrect deduction after payment'])->assertOk()->json('id');$this->postJson('/app-api/payroll/adjustments/'.$debit.'/review',['action'=>'approve','reason'=>'Would exceed paid balance'])->assertUnprocessable();$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertJsonPath('item.net_amount','32000.00')->assertJsonPath('totals.payable','32500.00')->assertJsonPath('totals.balance','0.00');}
 public function test_recovery_refund_restores_advance_debt_and_salary_credit_without_double_refund():void{$f=$this->fixture();$this->login($f);$this->loan($f);$run=$this->generate($f);$this->approve($run)->assertOk();$item=$this->item($run);$recovery=DB::table('advance_recoveries')->value('id');$d=['payroll_item_id'=>$item,'kind'=>'recovery_refund','amount'=>'5000','advance_recovery_id'=>$recovery,'reason'=>'Undo recovery posted by mistake'];$id=$this->postJson('/app-api/payroll/adjustments',$d)->assertOk()->json('id');$this->postJson('/app-api/payroll/adjustments/'.$id.'/review',['action'=>'approve','reason'=>'Restore the staff loan balance'])->assertOk();$this->getJson('/app-api/payroll/advances?campus_id='.$f['campus'])->assertJsonPath('rows.0.outstanding','12000.00');$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertJsonPath('totals.payable','32000.00');$id2=$this->postJson('/app-api/payroll/adjustments',$d)->assertOk()->json('id');$this->postJson('/app-api/payroll/adjustments/'.$id2.'/review',['action'=>'approve','reason'=>'Duplicate refund must not post'])->assertUnprocessable();}
 public function test_teacher_only_sees_own_payslip_and_leave_and_cannot_read_company_salary_setup():void{$f=$this->fixture();$b=$this->fixture('B');$this->login($f);$run=$this->generate($f);$this->approve($run)->assertOk();$item=$this->item($run);$this->login($b);$other=$this->generate($b);$this->approve($other)->assertOk();$this->login($f,true);$this->getJson('/app-api/payroll/self')->assertOk()->assertJsonPath('staff.id',$f['staff'])->assertJsonCount(1,'payslips');$this->getJson('/app-api/payroll/items/'.$item.'/payslip')->assertOk()->assertJsonPath('can_manage',false);$this->getJson('/app-api/payroll/items/'.$this->item($other).'/payslip')->assertNotFound();$this->preview($f)->assertForbidden();$this->getJson('/app-api/payroll/salaries?staff_profile_id='.$f['staff'])->assertForbidden();$this->postJson('/app-api/payroll/payments',$this->payData($f,$item))->assertForbidden();$this->getJson('/app-api/payroll/setup')->assertJsonCount(0,'staff')->assertJsonCount(0,'bank_accounts');}
 public function test_staff_attendance_is_not_preselected_corrections_are_reasoned_and_stale_versions_reject():void{$f=$this->fixture();$this->login($f);$this->getJson('/app-api/payroll/attendance?campus_id='.$f['campus'].'&date=2026-10-18')->assertOk()->assertJsonPath('rows.0.status',null);$d=['campus_id'=>$f['campus'],'date'=>'2026-10-18','records'=>[['staff_profile_id'=>$f['staff'],'status'=>'present','lock_version'=>0,'arrived_at'=>'08:00','remarks'=>null]]];$this->postJson('/app-api/payroll/attendance',$d)->assertOk();$this->postJson('/app-api/payroll/attendance',$d)->assertUnprocessable();$d['records'][0]['lock_version']=1;$d['records'][0]['status']='absent';$d['records'][0]['arrived_at']=null;$this->postJson('/app-api/payroll/attendance',$d)->assertUnprocessable();$d['reason']='Checked actual absence register';$this->postJson('/app-api/payroll/attendance',$d)->assertOk();$this->assertDatabaseHas('staff_attendance_records',['status'=>'absent','lock_version'=>2]);}
 public function test_leave_approval_links_attendance_and_cancellation_requires_review_before_payroll():void{$f=$this->fixture();$this->login($f,true);$leave=$this->postJson('/app-api/payroll/leaves',['staff_profile_id'=>$f['staff'],'starts_on'=>'2026-09-01','ends_on'=>'2026-09-01','leave_type'=>'paid','reason'=>'Approved family commitment'])->assertOk()->json('id');$this->postJson('/app-api/payroll/leaves/'.$leave.'/review',['action'=>'approve','lock_version'=>0,'reason'=>'Cannot approve own request'])->assertForbidden();$this->login($f);$this->postJson('/app-api/payroll/leaves/'.$leave.'/review',['action'=>'approve','lock_version'=>0,'reason'=>'Reviewed paid leave request'])->assertOk();$d=['campus_id'=>$f['campus'],'date'=>'2026-09-01','records'=>[['staff_profile_id'=>$f['staff'],'status'=>'present','lock_version'=>0]]];$this->postJson('/app-api/payroll/attendance',$d)->assertUnprocessable();$d['records'][0]['status']='leave';$d['records'][0]['leave_request_id']=$leave;$this->postJson('/app-api/payroll/attendance',$d)->assertOk();$this->postJson('/app-api/payroll/leaves/'.$leave.'/review',['action'=>'cancel','lock_version'=>1,'reason'=>'Staff worked instead of leave'])->assertOk();$this->preview($f)->assertUnprocessable();$d['records'][0]=['staff_profile_id'=>$f['staff'],'status'=>'present','lock_version'=>1];$d['reason']='Correct cancelled leave entry';$this->postJson('/app-api/payroll/attendance',$d)->assertOk();$this->preview($f)->assertOk();}
 public function test_appointments_overlap_cross_campus_month_and_closed_payroll_history_are_protected():void{$f=$this->fixture();$this->login($f);$d=['staff_profile_id'=>$f['staff'],'campus_id'=>$f['campus'],'starts_on'=>'2026-09-01','ends_on'=>null,'lock_version'=>0];$this->postJson('/app-api/payroll/employments',$d)->assertUnprocessable();$run=$this->generate($f);$this->approve($run)->assertOk();$this->putJson('/app-api/payroll/employments/'.$f['employment'],['staff_profile_id'=>$f['staff'],'campus_id'=>$f['campus'],'starts_on'=>'2026-08-01','ends_on'=>'2026-09-15','lock_version'=>0])->assertUnprocessable();$this->putJson('/app-api/payroll/employments/'.$f['employment'],['staff_profile_id'=>$f['staff'],'campus_id'=>$f['campus'],'starts_on'=>'2026-08-01','ends_on'=>'2026-09-30','lock_version'=>0])->assertOk();}
 public function test_policy_versions_require_explicit_owner_approval_and_cannot_rewrite_final_month():void{$f=$this->fixture();$this->login($f);$d=['campus_id'=>$f['campus'],'starts_on'=>'2026-10-15','rules'=>$this->rules('attendance')];$this->postJson('/app-api/payroll/policies',$d)->assertUnprocessable();$d['starts_on']='2026-10-01';$this->postJson('/app-api/payroll/policies',$d)->assertOk();$this->postJson('/app-api/payroll/policies',$d)->assertUnprocessable();$run=$this->generate($f);$this->approve($run)->assertOk();$d['starts_on']='2026-08-01';$this->postJson('/app-api/payroll/policies',$d)->assertUnprocessable();$this->preview($f,'2026-10')->assertUnprocessable();}
 public function test_campus_school_and_finance_overrides_do_not_leak_or_restore_access():void{$f=$this->fixture();$b=$this->fixture('B');$this->login($f);$this->preview($b)->assertNotFound();$this->postJson('/app-api/payroll/salaries',['staff_profile_id'=>$b['staff'],'starts_on'=>'2026-10-01','replace_previous'=>false,'items'=>[['name'=>'Basic','kind'=>'basic','amount'=>'100']]])->assertNotFound();$accountant=DB::table('roles')->where('name','accountant')->value('id');DB::table('membership_roles')->where('membership_id',$f['omid'])->update(['role_id'=>$accountant]);DB::table('school_role_permissions')->insert(['school_id'=>$f['sid'],'role_id'=>$accountant,'permission_id'=>DB::table('permissions')->where('name','payroll.manage')->value('id'),'enabled'=>false]);$this->seed(\Database\Seeders\PayrollAccessSeeder::class);$this->preview($f)->assertForbidden();}
 public function test_cross_school_salary_links_are_restricted_by_database_foreign_keys():void{$f=$this->fixture();$b=$this->fixture('B');$this->expectException(\Illuminate\Database\QueryException::class);DB::table('staff_employments')->insert(['school_id'=>$f['sid'],'staff_profile_id'=>$b['staff'],'campus_id'=>$f['campus'],'starts_on'=>'2026-11-01']);}
 public function test_guest_provider_and_missing_staff_payroll_license_cannot_bypass_scope():void{$this->getJson('/app-api/payroll/setup')->assertUnauthorized();$f=$this->fixture();$this->login($f);$license=\App\Services\LicenseService::ensure($f['sid']);DB::table('subscriptions')->insert(['school_id'=>$f['sid'],'plan_id'=>DB::table('plans')->value('id'),'license_id'=>$license->id,'kind'=>'paid','student_limit'=>1000,'campus_limit'=>2,'modules'=>json_encode(['fees']),'package_name'=>'Fees only','starts_on'=>'2026-01-01','ends_on'=>'2027-12-31','price'=>'100','status'=>'active']);$this->getJson('/app-api/payroll/setup')->assertForbidden();$provider=User::factory()->create();DB::table('platform_admins')->insert(['user_id'=>$provider->id,'active'=>true]);$this->actingAs($provider)->withSession(['school_id'=>$f['sid']])->getJson('/app-api/payroll/setup')->assertForbidden();}
}
